  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Olsalazine sodium had a systemic availability of 2.3% after a 1 g oral dose in fasting healthy volunteers, which is below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Tiludronic acid absolute oral bioavailability was 6% (range 2–11%) in healthy volunteers compared with IV, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Phosphanilic acid oral bioavailability in humans was about 4%, based on 24-hour urine excretion, below the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Nine of ten evidence molecules support low oral bioavailability, with numeric human absolute/systemic F values of 2.3%, <10%, 4%, 6%, and 3–10%, all below 20%. The only high-bioavailability records are in Molecule 3, which is discounted because the cards conflate aspirin and salicylate. Prediction: low.",
  "evidence_gaps": [
    "Molecule 3 records conflate aspirin and salicylate; inconsistent cards discounted as a provenance conflict.",
    "Molecules 4 and 5 provide only qualitative 'low/poor' bioavailability without numeric F values.",
    "Molecule 9 is a single-patient estimate based on assumed maximum physiological clearance."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

